// These are explicitly synthetic zero-credit fixtures. Ordinary battle cases
// never use these actor, timer or board assignments.
Board* Arena(LawnApp*app){auto b=app->mBoard;b->ClearCursor();for(auto z:b->mZombies)if(!z->mDead)z->DieNoLoot();for(auto p:b->mPlants)if(!p->mDead)p->Die();for(auto p:b->mProjectiles)if(!p->mDead)p->Die();for(auto c:b->mCoins)if(!c->mDead)c->Die();for(auto g:b->mGridItems)if(!g->mDead)g->GridItemDie();b->ProcessDeleteQueue();app->mEffectSystem->ProcessDeleteQueue();b->mZombieCountDown=b->mZombieCountDownStart=100000;b->mChallenge->mChallengeStateCounter=0;b->mChallenge->mChallengeGridX=0;return b;}
Zombie* Actor(Board*b,ZombieType type,float x,int row){Zombie::PreloadZombieResources(type);auto z=b->AddZombieInRow(type,row,0);z->mPosX=x;z->mX=int(x);z->UpdateReanim();Require(z->mBodyMaxHealth==270&&z->mBodyHealth==270&&z->mHasHead,"native mushroom actor did not initialize270HP");return z;}
void OneTick(LawnApp*app){const bool doubled=app->mDoubleGameSpeed;app->mDoubleGameSpeed=false;const int old=app->mBoard->mMainCounter;Tick(app,1);app->mDoubleGameSpeed=doubled;Require(app->mBoard->mMainCounter==old+1,"isolated native one-update measurement did not advance one native tick");}
